/* UCM Co-op Lab.  RoomBus transports real-time role-tagged input through Socket.IO. */
const $=s=>document.querySelector(s), clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v)), mean=a=>a.reduce((x,y)=>x+y,0)/Math.max(1,a.length), variance=a=>{let m=mean(a);return mean(a.map(v=>(v-m)**2))};
let state={A:50,B:50,rA:50,rB:50,room:'',connected:{A:false,B:false},running:false,start:0,hold:0,bestHold:0,score:0,combo:0,bestCombo:0,data:[],last:0,delay:[],settings:{task:'sum',target:100,a:1,b:1,tol:5,duration:20,hold:3,mode:'coop',moving:'static',amp:20,period:10,noise:'off',gainA:1,gainB:1,perturb:false,onset:10,newGain:.7,feedback:'total',timing:'concurrent',interval:250,delay:300}};
class RoomBus{constructor(room,role='host'){this.room=room;this.role=role;this.socket=io();this.socket.on('connect',()=>this.socket.emit('join-room',{room,role}));this.socket.on('presence',p=>{state.connected=p});this.socket.on('player-input',m=>{state[m.role]=m.value;state['r'+m.role]=m.raw;state.connected[m.role]=true});this.socket.on('host-feedback',m=>this.onFeedback?.(m))}send(m){if(m.type==='input')this.socket.emit('player-input',m);if(m.type==='feedback')this.socket.emit('host-feedback',m.payload)}close(){this.socket.disconnect()}}
let bus,history=[];
function task(){let s=state.settings,A=state.A*effGain('A'),B=state.B*effGain('B');if(s.task==='difference')return A-B;if(s.task==='weighted')return s.a*A+s.b*B;return A+B}
function target(){let s=state.settings,t=(performance.now()-state.start)/1000;if(!state.running)return s.target;if(s.moving==='sine')return s.target+s.amp*Math.sin(2*Math.PI*t/s.period);if(s.moving==='step')return s.target+(Math.floor(t/s.period)%2? s.amp:-s.amp);if(s.moving==='random')return s.target+Math.round(Math.sin(Math.floor(t/s.period)*912.3)*s.amp);return s.target}
function effGain(role){let s=state.settings,g=role==='A'?s.gainA:s.gainB;return s.perturb&&state.running&&role==='A'&&(performance.now()-state.start)/1000>=s.onset?s.newGain:g}
function noise(){return state.settings.noise==='high'?(Math.random()-.5)*10:state.settings.noise==='medium'?(Math.random()-.5)*5:state.settings.noise==='low'?(Math.random()-.5)*2:0}
function makeRoom(){state.room=Math.random().toString(36).slice(2,8).toUpperCase();bus?.close();bus=new RoomBus(state.room,'host');renderConnect();}
function url(role){return location.origin+location.pathname+'?room='+state.room+'&role='+role}
function renderConnect(){let r=$('#room');if(!state.room){r.innerHTML='<button class="primary" id="roomBtn">Create room</button>';$('#roomBtn').onclick=makeRoom;return}r.innerHTML=`<b>ROOM ${state.room}</b><div class="qr">${['A','B'].map(role=>`<div class="qrbox"><b>PLAYER ${role}</b><img alt="Player ${role} QR" src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(url(role))}"><a href="${url(role)}">${url(role)}</a></div>`).join('')}</div><p class="note">QRをそれぞれのスマホで開いてください。接続後は端末側で入力方式を選べます。</p>`}
function form(){let s=state.settings;return `<div class="tabs" id="tabs">${['INPUT','TASK','FEEDBACK','DIFFICULTY','PERTURBATION'].map((x,i)=>`<button class="${i?'':'active'}" data-tab="${x}">${x}</button>`).join('')}</div><div class="panel INPUT"><div class="controls"><label>Preset<select id="preset"><option>DEMO</option><option>PRESSURE COOP</option><option>TILT COOP</option><option>INDIVIDUAL</option><option>BLIND UCM</option><option>PERTURBATION</option></select></label><label>Player input (fallback)<select id="input"><option>Slider</option><option>Pressure-like</option><option>Tilt</option></select></label></div><p class="note">各スマホ側で入力方式を設定します。センサー非対応時はSliderへ切替可能です。</p></div><div class="panel TASK hidden"><div class="controls"><label>Task Type<select id="task"><option value="sum">SUM: x₁ + x₂</option><option value="difference">DIFFERENCE: x₁ − x₂</option><option value="weighted">WEIGHTED SUM</option></select></label><label>Target<input id="target" type="number" value="${s.target}"></label><label>weight a<input id="a" type="number" step=".1" value="${s.a}"></label><label>weight b<input id="b" type="number" step=".1" value="${s.b}"></label><label>Target mode<select id="moving"><option value="static">Static</option><option value="step">Step</option><option value="sine">Sine wave</option><option value="random">Random step</option></select></label><label>Amplitude / period<input id="amp" type="number" value="${s.amp}"></label></div></div><div class="panel FEEDBACK hidden"><div class="controls"><label>Game mode<select id="mode"><option value="coop">Cooperative</option><option value="individual">Individual</option><option value="blind">Blind cooperative</option></select></label><label>Feedback preset<select id="feedback"><option value="total">Total only</option><option value="all">Individual + Total</option><option value="individual">Individual only</option><option value="none">No feedback</option></select></label><label>Timing<select id="timing"><option value="concurrent">Concurrent</option><option value="reduced">Reduced</option><option value="delayed">Delayed</option><option value="terminal">Terminal</option></select></label></div></div><div class="panel DIFFICULTY hidden"><div class="controls"><label>Tolerance ±<input id="tol" type="number" value="${s.tol}"></label><label>Hold time (s)<input id="hold" type="number" value="${s.hold}"></label><label>Trial duration (s)<input id="duration" type="number" value="${s.duration}"></label><label>Input noise<select id="noise"><option value="off">OFF</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></label><label>A gain<input id="gainA" type="number" step=".1" value="${s.gainA}"></label><label>B gain<input id="gainB" type="number" step=".1" value="${s.gainB}"></label></div></div><div class="panel PERTURBATION hidden"><div class="controls"><label>Perturbation<select id="perturb"><option value="false">OFF</option><option value="true">ON (A)</option></select></label><label>Onset (s)<input id="onset" type="number" value="${s.onset}"></label><label>New A gain<input id="newGain" type="number" step=".1" value="${s.newGain}"></label></div></div>`}
function bindSettings(){['task','target','a','b','moving','amp','mode','feedback','timing','tol','hold','duration','noise','gainA','gainB','onset','newGain'].forEach(k=>$('#'+k).oninput=e=>state.settings[k]=isNaN(+e.target.value)?e.target.value:+e.target.value);$('#perturb').onchange=e=>state.settings.perturb=e.target.value==='true';$('#preset').onchange=e=>preset(e.target.value);$$('.tabs button').forEach(b=>b.onclick=()=>{$$('.tabs button').forEach(x=>x.classList.remove('active'));$$('.panel').forEach(x=>x.classList.add('hidden'));b.classList.add('active');$('.'+b.dataset.tab).classList.remove('hidden')})}
const $$=s=>[...document.querySelectorAll(s)];function preset(p){let s=state.settings;if(p==='DEMO')Object.assign(s,{task:'sum',target:100,tol:5,duration:20,feedback:'total'});if(p==='INDIVIDUAL')Object.assign(s,{mode:'individual',feedback:'individual'});if(p==='BLIND UCM')Object.assign(s,{mode:'blind',feedback:'total'});if(p==='PERTURBATION')Object.assign(s,{perturb:true,newGain:.7});renderHost()}
function renderHost(){$('#app').innerHTML=`<div class="head"><div><div class="eyebrow">COORDINATION LAB · UCM GAME</div><h1>二人で、ひとつの値を保つ。</h1><p class="sub">個人のばらつきが、協調によってタスクを安定させる体験型ラボ。</p></div><div class="status" id="gameState">SETUP</div></div><div class="grid"><section class="card setup"><h2>SETUP</h2>${form()}<div id="room" class="room"></div><details><summary>教育・解析のメモ</summary><p class="note">線形タスクの Jacobian J から null space（UCM）と row space（ORT）を定義します。SUMでは UCM=(1,-1)/√2、ORT=(1,1)/√2。ΔV=(V_UCM−V_ORT)/(V_UCM+V_ORT) と表示します。</p></details></section><section class="card live" id="live"><h2>PLAY</h2><div class="players"><div class="player"><span class="dot" id="dotA"></span>Player A <span id="conA">Disconnected</span></div><div class="player"><span class="dot" id="dotB"></span>Player B <span id="conB">Disconnected</span></div></div><div class="numbers"><div class="num" id="nA"><small>A</small><b>50</b></div><div class="num" id="nB"><small>B</small><b>50</b></div><div class="num"><small>TASK / TARGET</small><b id="nT">100 / 100</b></div></div><div class="gauge" id="gauge"><div class="targetline" id="tl"></div><div class="fill" id="fill"></div></div><p class="feedback" id="feedbackText">Roomを作成し、両プレイヤーを接続してください。</p><div class="row"><button class="primary" id="start">Start trial</button><button id="demo">Demo inputs</button><span class="pill" id="timer">00:20</span><span class="pill" id="score">Score 0 · Combo 0</span></div><div class="canvases"><canvas id="wave" class="plot"></canvas><canvas id="ucm" class="plot"></canvas></div></section><section class="card results"><h2>RESULT / UCM ANALYSIS</h2><div id="resultBody" class="note">Trial終了後、時系列・散布図・UCM分散がここに表示されます。</div></section></div>`;bindSettings();renderConnect();$('#start').onclick=start;$('#demo').onclick=()=>{state.connected.A=state.connected.B=true;let i=0;setInterval(()=>{if(!state.running)return;state.A=clamp(50+20*Math.sin(i/11));state.B=clamp(50-20*Math.sin(i++/11))},80)};requestAnimationFrame(tick)}
function start(){if(!state.connected.A||!state.connected.B){$('#feedbackText').textContent='接続を確認してください（Demo inputs で講義用の疑似入力を開始できます）。';return}state.running=true;state.start=performance.now();state.data=[];state.hold=state.bestHold=state.score=state.combo=state.bestCombo=0;$('#gameState').textContent='PLAY';$('#start').disabled=true}
function tick(now){
  if(!$('#live'))return;
  let s=state.settings,T=task()+noise(),tar=target(),err=T-tar,ok=Math.abs(err)<=s.tol;
  ['A','B'].forEach(r=>{$('#dot'+r).classList.toggle('on',state.connected[r]);$('#con'+r).textContent=state.connected[r]?'Connected':'Disconnected'});
  let show=s.feedback;
  $('#nA').classList.toggle('hidden',show==='total'||show==='none'); $('#nB').classList.toggle('hidden',show==='total'||show==='none');
  $('#nA b').textContent=state.A.toFixed(0); $('#nB b').textContent=state.B.toFixed(0); $('#nT').textContent=`${T.toFixed(1)} / ${tar.toFixed(1)}`;
  $('#fill').style.width=clamp(T/200*100)+'%'; $('#tl').style.left=clamp(tar/200*100)+'%'; $('#gauge').classList.toggle('success',ok);
  if(state.running){
    let elapsed=(now-state.start)/1000;
    if(ok){state.hold+=.016;state.score+=1;state.combo++;state.bestCombo=Math.max(state.bestCombo,state.combo)}
    else{state.bestHold=Math.max(state.bestHold,state.hold);state.hold=0;state.combo=0}
    if(now-state.last>80){
      state.last=now; state.data.push({timestamp:Date.now(),t:elapsed,raw_A:state.rA,raw_B:state.rB,normalized_A:state.A,normalized_B:state.B,effective_A:state.A*effGain('A'),effective_B:state.B*effGain('B'),A:state.A,B:state.B,T,tar,err,success:ok,gain_A:effGain('A'),gain_B:effGain('B'),input_type_A:'device',input_type_B:'device'});
      history.push({A:state.A,B:state.B,T,tar}); if(history.length>150)history.shift();
      bus?.send({type:'feedback',payload:{T,tar,err,ok,mode:s.mode,feedback:s.feedback}});
    }
    $('#timer').textContent=`${String(Math.max(0,s.duration-elapsed).toFixed(1)).padStart(4,'0')} s`; $('#score').textContent=`Score ${state.score} · Combo ${state.combo}`;
    $('#feedbackText').textContent=ok?`✓ TARGET ZONE · hold ${state.hold.toFixed(1)} / ${s.hold}s`:`Error ${err.toFixed(1)} · target ±${s.tol}`;
    if(state.hold>=s.hold)state.bestHold=state.hold;
    if(elapsed>=s.duration){state.running=false;state.bestHold=Math.max(state.bestHold,state.hold);$('#gameState').textContent='RESULT';$('#start').disabled=false;results()}
  }
  draw();requestAnimationFrame(tick);
}
function canvas(id){let c=$(id),r=c.getBoundingClientRect(),d=devicePixelRatio;c.width=r.width*d;c.height=r.height*d;let x=c.getContext('2d');x.scale(d,d);return[x,r.width,r.height]}
function draw(){if(!$('#wave'))return;let[x,w,h]=canvas('#wave');x.fillStyle='#0b172b';x.fillRect(0,0,w,h);x.strokeStyle='#294365';x.beginPath();x.moveTo(0,h/2);x.lineTo(w,h/2);x.stroke();let lines=[['A','#5eead4'],['B','#a78bfa'],['T','#60a5fa'],['tar','#fbbf24']];lines.forEach(([k,col])=>{x.strokeStyle=col;x.beginPath();history.forEach((v,i)=>{let px=i/149*w,py=h-clamp(v[k]/200)*h;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()});let[y,uw,uh]=canvas('#ucm');y.fillStyle='#0b172b';y.fillRect(0,0,uw,uh);let tar=target();y.strokeStyle='#fbbf24';y.beginPath();y.moveTo(0,uh-clamp(tar)/100*uh);y.lineTo(uw,uh-clamp(tar-100)/100*uh);y.stroke();history.forEach((p,i)=>{y.fillStyle=i===history.length-1?'#fff':'#5eead4';y.beginPath();y.arc(p.A/100*uw,uh-p.B/100*uh,i===history.length-1?5:2,0,7);y.fill()});y.fillStyle='#98a9c4';y.fillText('UCM: x₁ + x₂ = target',10,18)}
function results(){let d=state.data;if(!d.length)return;let mae=mean(d.map(v=>Math.abs(v.err))),rmse=Math.sqrt(mean(d.map(v=>v.err*v.err))),inside=100*mean(d.map(v=>+v.ok));let u=d.map(v=>(v.A-v.B)/Math.sqrt(2)),o=d.map(v=>(v.A+v.B)/Math.sqrt(2)),vu=variance(u),vo=variance(o),delta=(vu-vo)/(vu+vo||1),individual=variance(d.map(v=>v.A))+variance(d.map(v=>v.B)),taskVar=variance(d.map(v=>v.T));let explain=vu>vo?'Player AとPlayer Bの値は変動していましたが、その多くがTask Variableを変化させないUCM方向に生じていました。':'Taskに影響するORT方向の変動が相対的に大きく、さらに補償する余地があります。';$('#resultBody').innerHTML=`<div class="metric"><div><small>Score</small><b>${state.score}</b></div><div><small>Target内滞在率</small><b>${inside.toFixed(1)}%</b></div><div><small>MAE / RMSE</small><b>${mae.toFixed(2)} / ${rmse.toFixed(2)}</b></div><div><small>Best hold</small><b>${state.bestHold.toFixed(2)}s</b></div><div><small>V<sub>UCM</sub> / V<sub>ORT</sub></small><b>${vu.toFixed(2)} / ${vo.toFixed(2)}</b></div><div><small>ΔV</small><b>${delta.toFixed(3)}</b></div></div><h3>Why did you succeed?</h3><p>${explain}</p><p class="note">Individual variability ${individual.toFixed(1)} · Task variability ${taskVar.toFixed(1)}. 線形タスクではJ=[a,b]、UCMはJのnull space、ORTはJのrow spaceとして計算しています。PRODUCTなど非線形タスクの解析は無効です。</p><div class="row"><button id="csv">CSV export</button><button id="json">JSON export</button></div>`;$('#csv').onclick=()=>download('ucm-trial.csv',[Object.keys(d[0]).join(','),...d.map(x=>Object.values(x).join(','))].join('\n'),'text/csv');$('#json').onclick=()=>download('ucm-trial.json',JSON.stringify({settings:state.settings,samplingIntervalMs:80,data:d},null,2),'application/json')}
function download(name,text,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function player(role,room){let smoothing='medium',last=50,min=0,max=1,mode='slider',send=(raw)=>{let v=mode==='slider'?raw:clamp((raw-min)/(max-min)*100);let alpha=smoothing==='off'?1:smoothing==='low'?.55:smoothing==='medium'?.25:.12;last=last+(v-last)*alpha;bus.send({type:'input',role,value:clamp(last),raw});$('#value').textContent=last.toFixed(0);$('#bar').style.width=last+'%'};state.room=room;bus=new RoomBus(room,role);bus.onFeedback=f=>{let visible=f.feedback==='all'||f.feedback==='total'||(f.feedback==='individual'&&f.mode==='individual');$('#remote').textContent=visible?`TOTAL ${f.T.toFixed(0)} / TARGET ${f.tar.toFixed(0)} ${f.ok?'✓':''}`:'Feedback hidden';$('#remote').classList.toggle('success',f.ok)};$('#app').id='player';$('#app').innerHTML=`<div class="eyebrow">UCM CO-OP · PLAYER ${role}</div><h1>Player ${role}</h1><p class="sub">入力を送信して、相手とターゲットを維持してください。</p><div class="card"><label>Input mode <select id="mode"><option value="slider">Slider</option><option value="pressure">Pressure-like Touch</option><option value="tilt">Tilt</option></select></label><label>Smoothing <select id="smooth"><option value="off">OFF</option><option value="low">Low</option><option value="medium" selected>Medium</option><option value="high">High</option></select></label><div id="sliderBox"><input id="slider" class="vertical" type="range" min="0" max="100" value="50"></div><div id="pad" class="pad hidden"><div><strong>Touch Pad</strong><p>軽く触れる → 強く押す</p><button id="calMin">1. Light touch</button> <button id="calMax">2. Strong touch</button><p class="note" id="sensorNote"></p></div></div><button class="primary hidden" id="motion">Enable Motion Sensor</button><div class="big" id="value">50</div><div class="gauge"><div class="fill" id="bar" style="width:50%"></div></div><p id="remote" class="pill">Hostを待っています</p><p class="note">Touch圧が取れない端末ではSliderに切り替えてください。</p></div>`;$('#slider').oninput=e=>send(+e.target.value);$('#smooth').onchange=e=>smoothing=e.target.value;$('#mode').onchange=e=>{mode=e.target.value;$('#sliderBox').classList.toggle('hidden',mode!=='slider');$('#pad').classList.toggle('hidden',mode!=='pressure');$('#motion').classList.toggle('hidden',mode!=='tilt')};let area=e=>{let a=(e.width||e.radiusX*2||0)*(e.height||e.radiusY*2||0);if(!a){$('#sensorNote').textContent='この端末ではTouch Pressureを十分取得できません。Sliderへの切り替えを提案します。'}send(a)};$('#pad').onpointermove=e=>{if(e.buttons)area(e)};$('#calMin').onclick=()=>min=Math.max(.001,last);$('#calMax').onclick=()=>max=Math.max(min+.01,last);$('#motion').onclick=async()=>{try{if(DeviceOrientationEvent.requestPermission)await DeviceOrientationEvent.requestPermission();window.ondeviceorientation=e=>send((e.gamma??0)+45);$('#sensorNote').textContent='Tilt enabled: Left–Right axis'}catch(e){$('#sensorNote').textContent='モーション許可が得られません。Sliderを利用してください。'}}}
let p=new URLSearchParams(location.search);p.get('role')&&p.get('room')?player(p.get('role'),p.get('room')):renderHost();
